// Depends on tokenize (from tokenizer.js) and normalize (from normalize.js).

function analyze(text) {
  const tokens = tokenize(text);
  const count = tokens.length;
  const unique = [];
  const seen = {};
  const frequencies = {};

  for (let i = 0; i < tokens.length; i++) {
    const token = tokens[i];
    // Use Object.create(null) semantics via plain object but safe key handling
    if (!Object.prototype.hasOwnProperty.call(frequencies, token)) {
      frequencies[token] = 0;
      // Track first-seen order manually
      seen[token] = true;
      unique.push(token);
    }
    frequencies[token] += 1;
  }

  const summary = count + " tokens; " + unique.length + " unique";
  return {
    tokens: tokens,
    count: count,
    unique: unique,
    frequencies: frequencies,
    summary: summary
  };
}
